.create table StocksDaily (Ticker:string, Date:datetime, Range:real);

.create-or-alter function StocksDailyTransform() {
    Stocks | project Ticker, Date, Range = High - Low
}

.alter table StocksDaily policy update
@'[{"IsEnabled": true, "Source": "Stocks", "Query": "StocksDailyTransform()", "IsTransactional": false}]';

.ingest inline into table Stocks <| 2026-11-09,41.0,42.0,40.5,41.5,35.0,1000,HAL

StocksDaily | take 10

bike_agg2 | take 10

.show table Stocks policy caching
.alter table Stocks policy caching hot = 30d
.show table Stocks policy retention

Stocks | where Ticker contains "HA" | count
Stocks | where Ticker has "HAL" | count
Stocks | where Ticker == "HAL" | count

.create materialized-view StocksLatest on table Stocks
{ Stocks | summarize arg_max(Date, *) by Ticker }

